(()=>{'use strict';
const reduce=()=>!window.heavenlyMotionAllowed(),fine=matchMedia('(pointer:fine)').matches;
const fields=[],trails=[];let last=0,scrollDirty=true;
const vertex='attribute vec2 a;varying vec2 uv;void main(){uv=a*.5+.5;gl_Position=vec4(a,0.,1.);}';
const fragment=`precision mediump float;varying vec2 uv;uniform vec2 resolution;uniform vec2 mouse;uniform float time;uniform float dark;uniform float energy;
float wave(vec2 p){return sin(p.x*8.+sin(p.y*5.+time*.18))*cos(p.y*6.-time*.12)+sin(p.x*13.-p.y*8.+time*.09)*.35;}
void main(){vec2 p=uv;float dist=distance(p,mouse);p+=normalize(p-mouse+vec2(.0001))*sin(dist*28.-time*3.)*exp(-dist*7.)*.032*energy;float w=wave(p);vec2 cell=fract(gl_FragCoord.xy/5.);float dotmask=step(.52+w*.17,max(abs(cell.x-.5),abs(cell.y-.5))*2.);float shade=mix(.945,.17,dark)-(1.-dotmask)*mix(.13,.055,dark)*(.48+w*.25);gl_FragColor=vec4(vec3(shade)*mix(vec3(1.,.995,.96),vec3(.6,1.22,.96),dark),1.);}`;
function shader(gl,type,code){const s=gl.createShader(type);gl.shaderSource(s,code);gl.compileShader(s);if(!gl.getShaderParameter(s,gl.COMPILE_STATUS))throw Error(gl.getShaderInfoLog(s));return s}
document.querySelectorAll('[data-fluid]').forEach(host=>{const canvas=host.querySelector('.fluid-canvas');try{const gl=canvas.getContext('webgl',{alpha:false,antialias:false,powerPreference:'low-power'});if(!gl)return;const program=gl.createProgram();gl.attachShader(program,shader(gl,gl.VERTEX_SHADER,vertex));gl.attachShader(program,shader(gl,gl.FRAGMENT_SHADER,fragment));gl.linkProgram(program);if(!gl.getProgramParameter(program,gl.LINK_STATUS))throw Error('Shader unavailable');gl.useProgram(program);const buffer=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,buffer);gl.bufferData(gl.ARRAY_BUFFER,new Float32Array([-1,-1,1,-1,-1,1,1,1]),gl.STATIC_DRAW);const a=gl.getAttribLocation(program,'a');gl.enableVertexAttribArray(a);gl.vertexAttribPointer(a,2,gl.FLOAT,false,0,0);const uniforms=Object.fromEntries(['resolution','mouse','time','dark','energy'].map(n=>[n,gl.getUniformLocation(program,n)]));const field={host,canvas,gl,program,uniforms,x:.5,y:.5,energy:0,visible:false};host.addEventListener('pointermove',e=>{if(!fine)return;const r=host.getBoundingClientRect();field.x=(e.clientX-r.left)/r.width;field.y=1-(e.clientY-r.top)/r.height;field.energy=1;const h=host.querySelector('[data-fluid-text]');if(h&&!reduce()){h.style.setProperty('--warp-x',((field.x-.5)*5)+'px');h.style.setProperty('--warp-y',((field.y-.5)*3)+'px')}});canvas.addEventListener('webglcontextlost',e=>{e.preventDefault();field.visible=false;canvas.style.display='none'});fields.push(field)}catch{canvas.style.display='none'}});
function resize(){fields.forEach(f=>{const r=f.host.getBoundingClientRect(),scale=Math.min(fine?1.15:1,1440/Math.max(r.width,r.height));f.canvas.width=Math.max(1,Math.round(r.width*scale));f.canvas.height=Math.max(1,Math.round(r.height*scale));f.gl.viewport(0,0,f.canvas.width,f.canvas.height)});trails.forEach(t=>{const r=t.host.getBoundingClientRect();t.canvas.width=Math.round(r.width);t.canvas.height=Math.round(r.height)});scrollDirty=true}
function drawField(f,time){const {gl,uniforms:u}=f;gl.useProgram(f.program);gl.uniform2f(u.resolution,f.canvas.width,f.canvas.height);gl.uniform2f(u.mouse,f.x,f.y);gl.uniform1f(u.time,reduce()?0:time*.001);gl.uniform1f(u.dark,f.host.dataset.fluid==='dark'?1:0);gl.uniform1f(u.energy,reduce()?0:f.energy);gl.drawArrays(gl.TRIANGLE_STRIP,0,4);f.energy*=.96}
const images=PHOTO_POOL.map(src=>{const img=new Image();img.src='assets/'+src;return img});
function emit(t,x,y,ambient=false){if(t.particles.length>16)t.particles.shift();t.particles.push({x,y,vx:(Math.random()-.5)*(ambient?10:55),vy:ambient?-12:-30-Math.random()*35,age:0,life:ambient?6:2.6,angle:(Math.random()-.5)*.55,spin:(Math.random()-.5)*.15,image:images[Math.floor(Math.random()*images.length)],width:fine?110:80})}
document.querySelectorAll('[data-photo-trail]').forEach(host=>{const canvas=host.querySelector('.photo-canvas'),ctx=canvas.getContext('2d');if(!ctx)return;const t={host,canvas,ctx,particles:[],visible:false,emitted:0,ambient:0};host.addEventListener('pointermove',e=>{if(!fine||reduce()||e.target.closest('a,button'))return;const now=performance.now();if(now-t.emitted<100)return;const r=host.getBoundingClientRect();emit(t,e.clientX-r.left,e.clientY-r.top);t.emitted=now});host.addEventListener('pointerdown',e=>{if(reduce()||e.target.closest('a,button'))return;const r=host.getBoundingClientRect();for(let i=0;i<3;i++)emit(t,e.clientX-r.left+(i-1)*25,e.clientY-r.top)});trails.push(t)});
function drawTrail(t,dt,time){const {ctx,canvas}=t;ctx.clearRect(0,0,canvas.width,canvas.height);if(!reduce()&&time-t.ambient>1700&&t.particles.length<5){emit(t,canvas.width*(.2+Math.random()*.6),canvas.height*(.2+Math.random()*.4),true);t.ambient=time}t.particles=t.particles.filter(p=>p.age<p.life);t.particles.forEach(p=>{if(!reduce()){p.age+=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=12*dt;p.angle+=p.spin*dt}if(!p.image.complete||!p.image.naturalWidth)return;const alpha=Math.min(1,p.age/.15,(p.life-p.age)/.6),w=p.width,h=w*1.15;ctx.save();ctx.globalAlpha=Math.max(0,alpha)*.9;ctx.translate(p.x,p.y);ctx.rotate(p.angle);ctx.beginPath();ctx.roundRect(-w/2,-h/2,w,h,5);ctx.clip();const scale=Math.max(w/p.image.width,h/p.image.height);ctx.drawImage(p.image,-p.image.width*scale/2,-p.image.height*scale/2,p.image.width*scale,p.image.height*scale);ctx.restore()})}
const section=document.querySelector('.values-section'),cards=[...document.querySelectorAll('[data-stack-card]')],heading=document.querySelector('.values-heading'),catcher=document.querySelector('.catchphrase'),words=[...catcher.querySelectorAll('h2>span')];
function scrollEffects(){if(reduce()){cards.forEach(c=>{c.style.transform='';c.style.opacity='1'});heading.style.opacity='1';words.forEach(w=>{w.style.opacity=1;w.style.transform='none'});return}const vh=innerHeight,phase=-section.getBoundingClientRect().top/vh;cards.forEach((card,i)=>{const local=phase-(i+.65),behind=Math.max(0,Math.min(3,local)),y=local<0?-local*vh*1.15:-behind*22;card.style.transform=`translate(-50%,-50%) translateY(${y}px) scale(${1-behind*.065})`;card.style.zIndex=i+2;card.style.opacity=local<-.9?'0':'1'});heading.style.opacity=String(Math.max(.12,1-Math.max(0,phase-.3)*.6));const r=catcher.getBoundingClientRect(),p=(vh-r.top)/(vh+r.height*.35);words.forEach((w,i)=>{const v=Math.max(0,Math.min(1,(p-.1-i*.09)*3));w.style.opacity=v;w.style.transform=`translateY(${(1-v)*60}px) scale(${.9+v*.1})`})}
const io=new IntersectionObserver(entries=>{entries.forEach(entry=>{const f=fields.find(f=>f.host===entry.target),t=trails.find(t=>t.host===entry.target);if(f){f.visible=entry.isIntersecting;if(reduce()&&f.visible)drawField(f,0)}if(t){t.visible=entry.isIntersecting;if(t.visible&&!t.particles.length){emit(t,t.canvas.width*.63,t.canvas.height*.45,true);t.particles[0].age=.6}}})},{rootMargin:'100px'});[...new Set([...fields.map(f=>f.host),...trails.map(t=>t.host)])].forEach(el=>io.observe(el));
function frame(time){requestAnimationFrame(frame);if(document.hidden)return;if(scrollDirty){scrollEffects();scrollDirty=false}if(time-last<(fine?16:33))return;const dt=Math.min(.05,(time-last)/1000||.016);last=time;fields.forEach(f=>{if(f.visible&&!reduce())drawField(f,time)});trails.forEach(t=>{if(t.visible&&!reduce())drawTrail(t,dt,time)})}
window.addEventListener('scroll',()=>scrollDirty=true,{passive:true});window.addEventListener('resize',resize,{passive:true});window.addEventListener('motionchange',()=>{scrollDirty=true;fields.forEach(f=>drawField(f,0));trails.forEach(t=>drawTrail(t,0,0))});resize();document.fonts.ready.then(resize);requestAnimationFrame(frame);
})();
